  height: 80,
  borderRadius: 20,
  background: 'rgba(255,255,255,0.15)',
  backdropFilter: 'blur(16px)',
  WebkitBackdropFilter: 'blur(16px)',
  border: '1.5px solid rgba(255,255,255,0.40)',
