'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

const Header: React.FC = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const pathname = usePathname();
  const isContactPage = pathname === '/contact';

  const scrollToSection = (id: string) => {
    setIsMenuOpen(false);
    if (isContactPage) {
      window.location.href = `/#${id}`;
      return;
    }
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const navLinks = [
    { label: 'الرئيسية', id: 'hero' },
    { label: 'من أنا', id: 'about' },
    { label: 'أعمالي', id: 'portfolio' },
  ];

  return (
    <>
      <header
        className="absolute top-0 left-0 right-0 z-50"
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16 md:h-20">
            {/* Logo */}
            <div className="flex-shrink-0">
              <Link href="/">
                <img
                  src="https://assets.wuiltweb.com/6349047/05272025023540683524fc37a1e.png"
                  alt="خالد مودايفر"
                  className="h-12 w-auto object-contain logo-hover"
                />
              </Link>
            </div>

            {/* Desktop Navigation */}
            <nav className="hidden md:flex items-center gap-6">
              {navLinks.map((link) => (
                <button
                  key={link.id}
                  onClick={() => scrollToSection(link.id)}
                  className="font-bold text-base transition-colors duration-200 hover:opacity-80 text-white/85"
                >
                  {link.label}
                </button>
              ))}
            </nav>

            {/* CTA Button */}
            <div className="hidden md:block">
              <Link
                href="/contact"
                className="btn-tertiary text-sm"
              >
                اتصل بنا
              </Link>
            </div>

            {/* Mobile Hamburger */}
            <button
              className="md:hidden p-2"
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              aria-label="قائمة التنقل"
            >
              {isMenuOpen ? (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                  <path d="M18 6L6 18M6 6L18 18" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
                </svg>
              ) : (
                <svg width="26" height="19" viewBox="0 0 26 19" fill="none">
                  <path d="M0 0.8 L24 0.8" stroke="white" strokeWidth="2" strokeLinecap="round" />
                  <path d="M0 8.8 L24 8.8" stroke="white" strokeWidth="2" strokeLinecap="round" />
                  <path d="M9.6 16.8 L24 16.8" stroke="white" strokeWidth="2" strokeLinecap="round" />
                </svg>
              )}
            </button>
          </div>
        </div>

        {/* Mobile Menu */}
        {isMenuOpen && (
          <div className="md:hidden bg-[#3D7EE0] border-t border-white/20">
            <div className="px-4 py-4 flex flex-col gap-4">
              {navLinks.map((link) => (
                <button
                  key={link.id}
                  onClick={() => scrollToSection(link.id)}
                  className="text-white/85 font-bold text-base text-right py-2 border-b border-white/20 last:border-0"
                >
                  {link.label}
                </button>
              ))}
              <Link
                href="/contact"
                onClick={() => setIsMenuOpen(false)}
                className="btn-tertiary text-sm mt-2 text-center"
              >
                اتصل بنا
              </Link>
            </div>
          </div>
        )}
      </header>
    </>
  );
};

export default Header;
